mapper.select:
/* CastDepMapper.retrieveUserDepOperHrList */
SELECT
    A.DPTGT_NO,
    NVL(A.OPER_BGNG_HOUR, 0) AS OPER_BGNG_HOUR,
    NVL(A.OPER_END_HOUR, 0) AS OPER_END_HOUR
FROM PMOWN.TN_PM_SMLT_USER_DPTGT_OPER_HR A
WHERE 1 = 1
AND A.SMLT_ID = #{smltId}
AND A.TMNL_ID = #{tmnlId}
ORDER BY A.DPTGT_NO, A.OPER_HR_SN

mapper.delete:
/* CastDepMapper.deleteUserDepList */
DELETE FROM PMOWN.TN_PM_SMLT_USER_DPTGT
WHERE 1 = 1
AND SMLT_ID = #{smltId}
AND TMNL_ID = #{fcltTmnlId}

/* CastDepMapper.deleteUserDepOperHrList */
DELETE FROM PMOWN.TN_PM_SMLT_USER_DPTGT_OPER_HR
WHERE 1 = 1
AND SMLT_ID = #{smltId}
AND TMNL_ID = #{fcltTmnlId}

/* CastDepMapper.deleteUserScPlanList */
DELETE FROM PMOWN.TN_PM_SMLT_SCSH_OPER_PLAN
WHERE 1 = 1
AND SMLT_ID = #{smltId}
AND TMNL_ID = #{fcltTmnlId}

mapper.insert:
/* CastDepMapper.insertUserDepList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_DPTGT ( SMLT_ID, TMNL_ID, DPTGT_NO, OPER_YN, SCSH_CNTOM, GNRL_SRCH_CNTOM, SMART_PASS_SRCH_CNTOM, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{smltId}, #{fcltTmnlId}, #{dep.dptgtNo}, #{dep.oprYn}, #{dep.scshCntom}, #{dep.gnrlSrchCntom}, #{dep.smartPassSrchCntom}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL

/* CastDepMapper.insertUserDepOperHrList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_DPTGT_OPER_HR ( SMLT_ID, TMNL_ID, DPTGT_NO, OPER_HR_SN, OPER_BGNG_HOUR, OPER_END_HOUR, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{smltId}, #{fcltTmnlId}, #{dep.dptgtNo}, #{oprTimeIdx} + 1, #{oprTime.operBgngHour}, #{oprTime.operEndHour}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL

/* CastDepMapper.insertUserScPlanList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_SCSH_OPER_PLAN ( SMLT_ID, TMNL_ID, DPTGT_NO, PLAN_SN, OPER_BGNG_HOUR, OPER_END_HOUR, SCSH_CNTOM, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{smltId}, #{fcltTmnlId}, #{dep.dptgtNo}, #{planIdx} + 1, #{plan.operBgngHour}, #{plan.operEndHour}, #{plan.scshCntom}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL
